// Package postgres keeps the machine listener's authentication
// evidence in PostgreSQL via jackc/pgx (ADR-0109). The queries are
// generated by sqlc from queries.sql; inventory.sql is the read a
// person runs against it.
package postgres

import (
	"context"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/platform/internal/grn"
	"github.com/garamsh/garam/platform/internal/machine"
	"github.com/garamsh/garam/platform/internal/machine/postgres/db"
	"github.com/garamsh/garam/platform/internal/pgxerr"
	"github.com/garamsh/garam/platform/internal/pgxtype"
)

// Store satisfies [machine.Recorder].
type Store struct {
	q *db.Queries
}

// New returns a Store over pool.
func New(pool *pgxpool.Pool) *Store {
	return &Store{q: db.New(pool)}
}

// Record upserts the caller's row for the sighting's path. A sighting
// whose organization garam no longer holds writes nothing.
func (s *Store) Record(ctx context.Context, sighting machine.Sighting) error {
	params := db.RecordSightingParams{
		CallerGrn: sighting.Caller.String(),
		Path:      string(sighting.Path),
		OrgGrn:    grn.Org(sighting.Caller.Organization).String(),
	}
	// A listener sighting issued nothing and leaves it NULL.
	if !sighting.IssuedUntil.IsZero() {
		params.IssuedUntil = pgxtype.Timestamptz(sighting.IssuedUntil)
	}
	return pgxerr.Classify(s.q.RecordSighting(ctx, params), "record authentication evidence", nil, nil)
}
